package com.github.misterch0c.codewars.kyu6;

import java.util.Arrays;

/**
 * https://www.codewars.com/kata/57b06f90e298a7b53d000a86
 */
public class The_Supermarket_Queue {
    public static int queueTime(int[] customers, int n) {
        int[] time = new int[n];
        for (int i = 0; i < customers.length; i++) {
            int min = Arrays.stream(time).min().getAsInt();
            int index = Arrays.stream(time).indexOf(min);
            time[index] += customers[i];
        }
        return Arrays.stream(time).max().getAsInt();
    }
}
