package hu.bme.mit.y2018.hw1.hw1_1;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Szerezze meg a tanúsítványt és a known_hash-t a kérésből a 'certificate' és 'known_hash' kulcsok használatával. Térjen vissza 'Igaz'-ra, ha a tanúsítvány megegyezik a known_hash-szal, és 'Hamis'-ra egyébként.
     */
    public static boolean verify(String certificate, String known_hash) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(certificate.getBytes(StandardCharsets.UTF_8));
            String hashString = bytesToHex(hash);
            return hashString.equals(known_hash);
        } catch (NoSuchAlgorithmException e) {
            return false;
        }
    }

    private static String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }
}
