import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.util.Random;

public class Exercise01 {
    /**
     * A kérés eredményeit a'results' kulcs használatával szerezze be.
     * Hozzon létre egy ideiglenes fájlt UTF-8 kódolással,
     * írja bele az unicode karakterláncot az eredményekből,
     * és adja vissza a fájl elérési útját.
     * 
     * @param results Az írandó eredmények.
     * @return Az ideiglenes fájl elérési útja.
     */
    public static String writeResults(String[] results) {
        String fileName = "results.txt";
        File file = new File(fileName);
        try {
            FileWriter writer = new FileWriter(file);
            for (String result : results) {
                writer.write(result);
            }
            writer.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
        return file.getAbsolutePath();
    }

    public static void main(String[] args) {
        String[] results = new String[1000000];
        Random random = new Random();
        for (int i = 0; i < results.length; i++) {
            results[i] = String.valueOf(random.nextInt(1000000000));
        }
        System.out.println(writeResults(results));
    }
}
