//Given a positive integer n, find the number of non-negative integers less than or equal to n, whose binary representations do NOT contain consecutive ones. 
//
// 
//
// Example 1: 
//
// 
//Input: n = 5
//Output: 5
//Explanation: 
//Here are the non-negative integers <= 5 with their corresponding binary 
//representations:
//0 : 0
//1 : 1
//2 : 10
//3 : 11
//4 : 100
//5 : 101
//Among them, only integer 3 disobeys the rule (two consecutive ones) and the 
//other 5 satisfy the rule. 
//
// 
//
// Example 2: 
//
// 
//Input: n = 1
//Output: 2
// 
//
// 
//
// Constraints: 
//
// 
// 1 <= n <= 109 
// 
// Related Topics Math Bit Manipulation 
// 👍 106 👎 10


package com.github.sukritishah15.leetcode.editor.en;

public class Solution {
    public static void main(String[] args) {
        Solution solution = new Solution();
        System.out.println(solution.bitwiseComplement(5));
    }

    public int bitwiseComplement(int n) {
        int i = 1;
        while (i <= n) {
            i = i << 1;
        }
        return i - 1 - n;
    }
}
