package com.github.joshlong.leetcode.problems.easy.easy_1001_1100.easy_1001_1010.easy_1001_1005;

import java.util.Arrays;

/**
 * https://leetcode.com/problems/maximize-sum-of-array-after-k-negations/
 *
 * @author 
 */
public class Solution1005 {
    public int largestSumAfterKNegations(int[] A, int K) {
        Arrays.sort(A);
        int sum = 0;
        for (int i = 0; i < A.length; i++) {
            if (A[i] < 0) {
                if (K % 2 == 0) {
                    A[i] = -A[i];
                } else {
                    if (i == 0 || A[i - 1] > 0) {
                        A[i] = -A[i];
                    }
                }
                K--;
            }
            sum += A[i];
        }
        if (K % 2 == 1) {
            sum -= 2 * A[0];
        }
        return sum;
    }
}
