package com.github.hcsp.io;

import java.io.File;
import java.io.FileFilter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class FileSearch {
    /**
     * 给定一个目录，返回一个存储在该目录下所有.java后缀名的文件的列表。
     *
     * <p>例如，给定目录<code>dir</code>的路径为"c:\\temp\\java"，则有如下文件： <br>
     * <code>
     * c:\\temp\\java\\a.java <br>
     * c:\\temp\\java\\b.java <br>
     * c:\\temp\\java\\c.java <br>
     * </code>
     *
     * <p>请实现该函数，将上述文件列表作为一个<strong>Set</strong>集合返回。
     *
     * <p>注意，不允许将输入流、文件、目录等任何形式的文件读取到内存全部分配进内存中。
     *
     * @param dir 目录
     * @return 该目录下所有.java后缀名的文件的列表
     */
    public static Set<File> search(String dir) {
        File file = new File(dir);
        File[] files = file.listFiles(new FileFilter() {
            @Override
            public boolean accept(File pathname) {
                return pathname.getName().endsWith(".java");
            }
        });
        return new Set<File>(Arrays.asList(files));
    }

    public static void main(String[] args) throws IOException {
        Set<File> files = search("C:\\Users\\Administrator\\Desktop\\java");
        for (File file : files) {
            System.out.println(file.getName() + ": " + file.length());
        }
    }

    public static class Set<T> extends ArrayList<T> {
        public Set(List<T> list) {
            super(list);
        }

        @Override
        public boolean add(T t) {
            if (contains(t)) {
                return false;
            }
            return super.add(t);
        }
    }
}

