package com.github.saphyra.apphub.service.impl.util;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.stream.Collectors;

import org.springframework.stereotype.Component;

@Component
public class FileUtil {
    public static List<String> getFiles(String path) {
        return getFiles(Paths.get(path));
    }

    public static List<String> getFiles(Path path) {
        return Files.walk(path)
           .filter(Files::isRegularFile)
           .map(Path::toString)
           .collect(Collectors.toList());
    }

    public static void deleteFile(String path) {
        deleteFile(Paths.get(path));
    }

    public static void deleteFile(Path path) {
        try {
            Files.delete(path);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public static void deleteDirectory(String path) {
        deleteDirectory(Paths.get(path));
    }

    public static void deleteDirectory(Path path) {
        try {
            Files.walk(path)
               .sorted(Path::compareTo)
               .map(Path::toFile)
               .forEach(File::delete);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public static void createDirectory(String path) {
        createDirectory(Paths.get(path));
    }

    public static void createDirectory(Path path) {
        try {
            Files.createDirectories(path);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}
