            // Assume input is "[1, 2, 3]"
            String clean = numbersJson.replace("[", "").replace("]", "");
            if (clean.trim().isEmpty()) {
                throw new IllegalArgumentException("Empty list");
            }
            String[] parts = clean.split(",");
            double sum = 0;
            for (String p : parts) {
                sum += Double.parseDouble(p.trim());
