package com.github.michaelwittig.hackerrank.challenges.java.introduction;

import java.util.Scanner;

/**
 * https://www.hackerrank.com/challenges/java-loops-i
 */
public class JavaLoopsII {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int t = in.nextInt();
        for (int i = 0; i < t; i++) {
            int a = in.nextInt();
            int b = in.nextInt();
            int n = in.nextInt();
            int result = a;
            for (int j = 0; j < n; j++) {
                result = result + (int) Math.pow(2, j) * b;
                System.out.print(result + " ");
            }
            System.out.println();
        }
    }
}
