public class Isogram {
    public static boolean isIsogram(String word) {
        Set<Character> letters = new HashSet<>();
        for (char c : word.toLowerCase().toCharArray()) {
            if (c == '-' || c =='') {
                continue;
            }
            if (letters.contains(c)) {
                return false;
            }
            letters.add(c);
        }
        return true;
    }
}
