package com.github.michael_b.security;

import com.github.michael_b.security.exceptions.InvalidPasswordException;
import com.github.michael_b.security.exceptions.InvalidUsernameException;
import com.github.michael_b.security.exceptions.UserNotFoundException;
import com.github.michael_b.security.exceptions.UsernameAlreadyExistsException;
import com.github.michael_b.security.models.User;

import java.util.ArrayList;
import java.util.List;

public class Security {
    private List<User> users;

    public Security() {
        this.users = new ArrayList<>();
    }

    public void addUser(String username, String password) throws UsernameAlreadyExistsException, InvalidUsernameException, InvalidPasswordException {
        if (username.length() < 3) {
            throw new InvalidUsernameException();
        }
        if (password.length() < 8) {
            throw new InvalidPasswordException();
        }
        if (this.users.stream().anyMatch(user -> user.getUsername().equals(username))) {
            throw new UsernameAlreadyExistsException();
        }
        this.users.add(new User(username, password));
    }

    public User login(String username, String password) throws UserNotFoundException, InvalidPasswordException {
        if (this.users.stream().noneMatch(user -> user.getUsername().equals(username))) {
            throw new UserNotFoundException();
        }
        if (!this.users.stream().anyMatch(user -> user.getUsername().equals(username) && user.getPassword().equals(password))) {
            throw new InvalidPasswordException();
        }
        return this.users.stream().filter(user -> user.getUsername().equals(username)).findFirst().get();
    }
}
