### 2.2.2 编写测试

在 `src/test/java/com/example/demo/ClassXTest.java` 中编写测试。

```java
package com.example.demo;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.context.SpringBootTest.WebEnvironment;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.boot.web.server.LocalServerPort;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

@SpringBootTest(webEnvironment = WebEnvironment.RANDOM_PORT)
public class ClassXTest {

    @LocalServerPort
    private int port;

    @Autowired
    private TestRestTemplate restTemplate;

    @Test
    public void testLogin() {
        ResponseEntity<String> response = restTemplate.getForEntity("http://localhost:" + port + "/login?username=user", String.class);
        assertEquals(HttpStatus.OK, response.getStatusCode());
        assertEquals("user", response.getBody());
    }

    @Test
    public void testLogout() {
        ResponseEntity<String> response = restTemplate.getForEntity("http://localhost:" + port + "/logout", String.class);
        assertEquals(HttpStatus.OK, response.getStatusCode());
        assertEquals("user", response.getBody());
    }

    @Test
    public void testDashboard() {
        ResponseEntity<String> response = restTemplate.getForEntity("http://localhost:" + port + "/dashboard", String.class);
        assertEquals(HttpStatus.OK, response.getStatusCode());
        assertTrue(response.getBody().contains("user"));
    }
}
```

