public class Ex1 {
    public static void main(String[] args) {
        Path path = Paths.get("src/main/resources/ex1.txt");
        try {
            List<String> lines = Files.readAllLines(path);
            List<String> result = lines.stream()
                   .map(line -> line.split(" "))
