package com.github.michaelruocco.codewars.kata.kyu6;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/**
 * You are given an array (which will have a length of at least 3, but could be very large) containing integers. The
 * array is either entirely comprised of odd integers or entirely comprised of even integers except for a single
 * integer N. Write a method that takes the array as an argument and returns this "outlier" N.
 * 
 * Examples
 * [2, 4, 0, 100, 4, 11, 2602, 36]
 * Should return: 11 (the only odd number)
 * 
 * [160, 3, 1719, 19, 11, 13, -21]
 * Should return: 160 (the only even number)
 * 
 * @author 
 */
public class FindTheParityOutlier {

    public static int find(int[] integers) {
        List<Integer> odds = Arrays.stream(integers).filter(i -> i % 2!= 0).boxed().collect(Collectors.toList());
        List<Integer> evens = Arrays.stream(integers).filter(i -> i % 2 == 0).boxed().collect(Collectors.toList());
        return odds.size() > evens.size()? evens.get(0) : odds.get(0);
    }

}
