package com.github.michael_b.code_golf.challenges.java;

import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;

public class ClassX {
    /**
     * Luo staattinen vektori, salaus käyttäen AES:ää ja CBC-tilaa. 
     * Sitten salaa tiedot käyttäen salausta täyttämällä lohkokoko, ja palauta se.
     * @param data: Salattavat tiedot.
     * @param key: Salausavain.
     * @return: Salatut tiedot.
     */
    public static String encrypt(String data, String key) {
        try {
            IvParameterSpec iv = new IvParameterSpec(new byte[16]);
            SecretKeySpec skeySpec = new SecretKeySpec(key.getBytes(), "AES");
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5PADDING");
            cipher.init(Cipher.ENCRYPT_MODE, skeySpec, iv);
            byte[] encrypted = cipher.doFinal(data.getBytes());
            return Base64.getEncoder().encodeToString(encrypted);
        } catch (Exception ex) {
            ex.printStackTrace();
        }
        return null;
    }
}
