public class FileAccessor {
    public static void main(String[] args) throws IOException {
        File file = new File("test.txt");
        if (file.exists()) {
            file.delete();
        }
        file.createNewFile();
        write(file, "Hello");
        write(file, "World");
        write(file, "!");
        System.out.println(read(file));
