	public static void main(String[] args) {
		System.out.println(findOutlier(new int[] { 2, 4, 0, 100, 4, 11, 2602, 36 }));
		System.out.println(findOutlier(new int[] { 160, 3, 1719, 19, 11, 13, -21 }));
	}

