public byte[] read_bytes(int num_bytes) throws IOException {
    byte[] buffer = new byte[num_bytes];
    int bytes_read = 0;
    while (bytes_read < num_bytes) {
        int read_bytes = this._stream.read(buffer, bytes_read, num_bytes - bytes_read);
        if (read_bytes == -1) {
            throw new EOFError("EOF reached while reading " + num_bytes + " bytes");
