public class WebUtils {

    public static String get(String url) throws IOException {
        return get(url, StandardCharsets.UTF_8);
    }

    public static String get(String url, String charset) throws IOException {
        return get(new URL(url), charset);
    }

    public static String get(URL url) throws IOException {
        return get(url, StandardCharsets.UTF_8);
    }

    public static String get(URL url, String charset) throws IOException {
        try (InputStream is = url.openStream();
             Reader reader = new InputStreamReader(is, charset)) {
            return read(reader);
        }
    }

    public static String read(Reader reader) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = reader.read())!= -1) {
            sb.append((char) c);
        }
        return sb.toString();
    }

    public static String read(HttpURLConnection connection) throws IOException {
        try (InputStream is = connection.getInputStream();
             Reader reader = new InputStreamReader(is, connection.getContentEncoding())) {
            return read(reader);
        }
    }
}
