    public static int[] middle(int[] arr) {
        int[] result = new int[2];
        int length = arr.length;
        if (length % 2 == 0) {
            result[0] = arr[length / 2 - 1];
            result[1] = arr[length / 2];
        } else {
            result[0] = arr[length / 2];
            result[1] = arr[length / 2];
        }
        return result;
    }
