public class ClassX {
    /**
     * Szerezze meg a kérés x-forwarded-for fejlécének információját, és ellenőrizze, hogy helyi IP-címről van-e szó. Ha nem helyi IP-cím, emeljen ki egy kivételt. 
     * : visszatérés: Az x-forwarded-for fejléc.
     */
    public static String getXForwardedFor(HttpServletRequest request) {
        String xForwardedFor = request.getHeader("x-forwarded-for");
        if (xForwardedFor == null) {
            throw new IllegalArgumentException("x-forwarded-for header is missing");
        }
        String[] ipAddresses = xForwardedFor.split(",");
        for (String ipAddress : ipAddresses) {
            if (isLocalAddress(ipAddress)) {
                return ipAddress;
            }
        }
        throw new IllegalArgumentException("x-forwarded-for header contains non-local address");
    }

    private static boolean isLocalAddress(String ipAddress) {
        return ipAddress.equals("127.0.0.1") || ipAddress.equals("0:0:0:0:0:0:0:1");
    }
}
