package com.github.h0tk3y.java.codewars.kyu6;

import java.util.Arrays;

/**
 * https://www.codewars.com/kata/the-supermarket-queue/train/java
 */
public class The_Supermarket_Queue {
    public static int queueTime(int[] customers, int n) {
        int[] tills = new int[n];
        for (int i = 0; i < customers.length; i++) {
            int min = 0;
            for (int j = 0; j < tills.length; j++) {
                if (tills[j] < tills[min]) {
                    min = j;
                }
            }
            tills[min] += customers[i];
        }
        return Arrays.stream(tills).max().getAsInt();
    }
}
