package com.github.h0tk3y.java.codewars.kyu6;

/**
 * https://www.codewars.com/kata/sum-of-digits-digital-root/train/java
 */
public class Sum_of_Digits_Digital_Root {
    public static int digital_root(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        if (sum > 9) {
            return digital_root(sum);
        }
        return sum;
    }
}
