package it.polito.tdp.borders.model;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.jgrapht.Graph;
import org.jgrapht.Graphs;
import org.jgrapht.graph.DefaultWeightedEdge;
import org.jgrapht.graph.SimpleWeightedGraph;

import it.polito.tdp.borders.db.BordersDAO;

public class Model {

	private BordersDAO dao;
	private Map<Integer, Country> countryMap;
	private Graph<Country, DefaultWeightedEdge> grafo;

	public Model() {
		this.dao = new BordersDAO();
		this.countryMap = new HashMap<>();
		this.grafo = new SimpleWeightedGraph<>(DefaultWeightedEdge.class);
	}

	public List<Country> getCountries() {
		return new ArrayList<>(this.countryMap.values());
	}

	public void creaGrafo(int anno) {
		this.countryMap.clear();
		this.grafo.clear();

		List<Country> countries = this.dao.getCountry(anno);
		for (Country c : countries) {
			this.countryMap.put(c.getCountryId(), c);
		}

		List<Border> bordi = this.dao.getBorder(anno);
		for (Border b : bordi) {
			Graphs.addEdgeWithVertices(this.grafo, this.countryMap.get(b.getCountry1()), this.countryMap.get(b.getCountry2()),
					b.getWeight());
		}
	}

	public List<Country> getCountryNeighbors(Country country) {
		List<Country> result = new ArrayList<>();
		for (Country c : this.grafo.vertexSet()) {
			if (this.grafo.containsEdge(country, c)) {
				result.add(c);
			}
		}
		return result;
	}

