package com.github.misterchangbin.codewars.kyu6;

import java.util.Arrays;

/**
 * https://www.codewars.com/kata/57b06f90e298a7b53d000a86
 */
public class TheSupermarketQueue {
    public static int queueTime(int[] customers, int n) {
        int[] tills = new int[n];
        for (int i = 0; i < customers.length; i++) {
            int min = Arrays.stream(tills).min().getAsInt();
            int index = Arrays.stream(tills).indexOf(min);
            tills[index] += customers[i];
        }
        return Arrays.stream(tills).max().getAsInt();
    }
}
