package com.github.khoapham.code.service;

import com.github.khoapham.code.model.Code;
import com.github.khoapham.code.model.CodeRequest;
import com.github.khoapham.code.model.CodeResponse;
import com.github.khoapham.code.model.CodeType;
import com.github.khoapham.code.model.CodeTypeRequest;
import com.github.khoapham.code.model.CodeTypeResponse;
import com.github.khoapham.code.repository.CodeRepository;
import com.github.khoapham.code.repository.CodeTypeRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.List;

@Service
public class CodeService {
    @Autowired
    private CodeRepository codeRepository;

    @Autowired
    private CodeTypeRepository codeTypeRepository;

    public CodeResponse getCode(CodeRequest codeRequest) {
        Code code = codeRepository.findByCode(codeRequest.getCode());
        if (code == null) {
            return null;
        }
        return new CodeResponse(code.getCode(), code.getDescription());
    }

    public List<CodeTypeResponse> getCodeTypes() {
        return codeTypeRepository.findAll();
    }

    public CodeTypeResponse getCodeType(CodeTypeRequest codeTypeRequest) {
        CodeType codeType = codeTypeRepository.findByCode(codeTypeRequest.getCode());
        if (codeType == null) {
            return null;
        }
        return new CodeTypeResponse(codeType.getCode(), codeType.getDescription());
    }
}
