package com.github.shanemcgrath.codewars.kyu6;

import java.util.Arrays;

/**
 * https://www.codewars.com/kata/57b06f90e298a7b53d000a86
 */
public class TheSupermarketQueue {
    public static int queueTime(int[] customers, int n) {
        int[] times = new int[n];
        for (int customer : customers) {
            int min = Arrays.stream(times).min().getAsInt();
            int index = Arrays.stream(times).indexOf(min);
            times[index] += customer;
        }
        return Arrays.stream(times).max().getAsInt();
    }
}
