package com.github.shanemcgrath.codewars.kyu6;

import java.util.Arrays;

/**
 * https://www.codewars.com/kata/5526fc09a1bbd946250002dc
 */
public class FindTheParityOutlier {
    public static int find(int[] integers) {
        int odd = 0;
        int even = 0;
        for (int integer : integers) {
            if (integer % 2 == 0) {
                even++;
            } else {
                odd++;
            }
        }
        return odd > even? Arrays.stream(integers).filter(i -> i % 2!= 0).findFirst().getAsInt() : Arrays.stream(integers).filter(i -> i % 2 == 0).findFirst().getAsInt();
    }
}
